// generates supabase/seed.sql: reference data only (supported stocks, achievement
// definitions). beef never seeds people, posts, duels or balances.
import { writeFileSync } from "node:fs";
import { ASSETS } from "../src/lib/market/assets";
import { ACHIEVEMENTS } from "../src/lib/score";

const q = (v: unknown) => (typeof v === "boolean" ? String(v) : `'${String(v).replace(/'/g, "''")}'`);
const out = [
  "-- generated by scripts/generate-seed-sql.ts. reference data only: no users or activity.",
  "insert into stock_assets (ticker, name, sector, tokenized) values",
  ASSETS.map((a) => `  (${q(a.ticker)}, ${q(a.name)}, ${q(a.sector)}, ${q(false)})`).join(",\n") + "\non conflict (ticker) do update set name = excluded.name, sector = excluded.sector;",
  "",
  "insert into achievements (id, name, description, emoji) values",
  ACHIEVEMENTS.map((a) => `  (${q(a.id)}, ${q(a.name)}, ${q(a.description)}, ${q(a.emoji)})`).join(",\n") + "\non conflict (id) do update set name = excluded.name, description = excluded.description, emoji = excluded.emoji;",
  "",
];
writeFileSync("supabase/seed.sql", out.join("\n"));
console.log("wrote supabase/seed.sql (reference data only)");
